export const GATES=[[0,12,2.4],[0,30,3.4],[8,47,4.5],[24,56,3.2],[42,48,2.5],[47,28,4],[37,8,3],[18,-1,2.6]];
export class FlightState {
 constructor(){this.reset()}
 reset(){Object.assign(this,{x:0,y:0,z:1.2,vx:0,vy:0,vz:0,speed:0,throttle:.5,pitch:0,roll:0,heading:0,crashed:false,paused:true,gate:0,elapsed:0,complete:false})}
 step(dt,keys,axes={}){if(this.paused||this.crashed||this.complete)return;dt=Math.min(dt,.03);this.elapsed+=dt;const k=c=>keys.has(c)?1:0,mix=1-Math.exp(-dt*6);this.pitch+=(Math.max(-1,Math.min(1,k('KeyS')-k('KeyW')-(axes.pitch||0)))*.5-this.pitch)*mix;this.roll+=(Math.max(-1,Math.min(1,k('KeyD')-k('KeyA')+(axes.roll||0)))*.5-this.roll)*mix;this.heading+=dt*1.35*Math.max(-1,Math.min(1,k('ArrowLeft')+k('KeyQ')-k('ArrowRight')-k('KeyE')+(axes.yaw||0)));const lift=Math.max(-1,Math.min(1,k('ArrowUp')-k('ArrowDown')+(axes.throttle||0)));this.throttle=.5+lift*.35;const upx=Math.cos(this.heading)*Math.sin(this.roll)+Math.sin(this.heading)*Math.sin(this.pitch)*Math.cos(this.roll),upy=Math.sin(this.heading)*Math.sin(this.roll)-Math.cos(this.heading)*Math.sin(this.pitch)*Math.cos(this.roll),upz=Math.cos(this.pitch)*Math.cos(this.roll);const thrust=9.81/Math.max(.65,upz)+lift*8;this.vx=(this.vx+upx*thrust*dt)*Math.exp(-dt*.45);this.vy=(this.vy+upy*thrust*dt)*Math.exp(-dt*.45);this.vz=(this.vz+(upz*thrust-9.81)*dt)*Math.exp(-dt*1.6);this.x+=this.vx*dt;this.y+=this.vy*dt;this.z+=this.vz*dt;this.speed=Math.hypot(this.vx,this.vy,this.vz);if(this.z<.08){if(Math.abs(this.vz)>3||this.speed>5)this.crashed=true;this.z=.08;this.vz=0;this.vx*=.9;this.vy*=.9}if(Math.hypot(this.x,this.y)>320||this.z>140)this.crashed=true;const g=GATES[this.gate];if(g&&Math.hypot(this.x-g[0],this.y-g[1],this.z-g[2])<1.6){this.gate++;if(this.gate===GATES.length)this.complete=true}}
}
